BY_ID = {e['id']: e for e in EXAMPLES}

def code_lines(ex):
    return [l for g, _ in ex['groups'] for l in g]

def code_text(ex):
    return '\n'.join(code_lines(ex))

def run_text(ex):
    return '\n'.join(list(ex.get('setup', [])) + code_lines(ex))
